  1: 'Sword', 2: 'Dagger', 3: 'Mace', 4: 'Axe', 5: 'Claw', 6: 'Polearm',
  7: 'Chainsaw', 8: 'Staff', 9: 'Cane', 10: 'Wand', 11: 'Book', 12: 'Spellblade',
